{
  "question": "What is the difference between classical conditioning and operant conditioning in learning theory?",
  "approach": {
    "objective": "Compare classical and operant conditioning by their mechanisms, timing, learner behavior, and examples.",
    "steps": [
      "Define classical conditioning as learning through association between a neutral stimulus and an unconditioned stimulus, producing a conditioned response.",
      "Define operant conditioning as learning through consequences, such as reinforcement or punishment, that increase or decrease the likelihood of a voluntary behavior.",
      "Contrast the learner's role: the response in classical conditioning is usually involuntary, while operant conditioning involves voluntary behavior.",
      "Contrast timing: in classical conditioning, the response follows a stimulus; in operant conditioning, the consequence follows the behavior.",
      "Contrast examples: Pavlov's dog salivating to a bell illustrates classical conditioning; a rat pressing a lever to receive food illustrates operant conditioning.",
      "Summarize the core difference: classical conditioning is stimulus-response association, while operant conditioning is behavior-consequence association."
    ],
    "key_contrast": {
      "classical_conditioning": {
        "learning_type": "Association between stimuli",
        "response_type": "Involuntary or reflexive",
        "example": "A dog learns to salivate when hearing a bell after repeated pairings with food."
      },
      "operant_conditioning": {
        "learning_type": "Association between behavior and consequence",
        "response_type": "Voluntary behavior",
        "example": "A student studies harder to earn praise or avoid a bad grade."
      }
    },
    "final_answer": {
      "main_difference": "Classical conditioning involves learning associations between stimuli that trigger involuntary responses, while operant conditioning involves learning associations between voluntary behaviors and their consequences, such as reinforcement or punishment."
    }
  }
}

